item.description:
 &lt;h1 id=&#34;前言&#34;&gt;&lt;a href=&#34;#前言&#34; class=&#34;headerlink&#34; title=&#34;前言&#34;&gt;&lt;/a&gt;前言&lt;/h1&gt;&lt;p&gt;XXL-JOB是一个分布式任务调度平台，其核心设计目标是开发迅速、学习简单、轻量级、易扩展。现已开放源代码并接入多家公司线上产品线，开箱即用。&lt;/p&gt;
&lt;p&gt;项目地址：&lt;a href=&#34;https://github.com/xuxueli/xxl-job&#34;&gt;https://github.com/xuxueli/xxl-job&lt;/a&gt;&lt;/p&gt;
&lt;h1 id=&#34;部署&#34;&gt;&lt;a href=&#34;#部署&#34; class=&#34;headerlink&#34; title=&#34;部署&#34;&gt;&lt;/a&gt;部署&lt;/h1&gt;&lt;h2 id=&#34;MySQL数据库初始化&#34;&gt;&lt;a href=&#34;#MySQL数据库初始化&#34; class=&#34;headerlink&#34; title=&#34;MySQL数据库初始化&#34;&gt;&lt;/a&gt;MySQL数据库初始化&lt;/h2&gt;&lt;p&gt;sql:&lt;/p&gt;
&lt;figure class=&#34;highlight sql&#34;&gt;&lt;table&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;#cat sss.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;#&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;# XXL&lt;span class=&#34;operator&#34;&gt;-&lt;/span&gt;JOB v2&lt;span class=&#34;number&#34;&gt;.2&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;# Copyright (c) &lt;span class=&#34;number&#34;&gt;2015&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;-&lt;/span&gt;present, xuxueli.&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE&lt;/span&gt; database if &lt;span class=&#34;keyword&#34;&gt;NOT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;EXISTS&lt;/span&gt; `xxl_job` &lt;span class=&#34;keyword&#34;&gt;default&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;character set&lt;/span&gt; utf8mb4 &lt;span class=&#34;keyword&#34;&gt;collate&lt;/span&gt; utf8mb4_unicode_ci;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;use `xxl_job`;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;SET&lt;/span&gt; NAMES utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_info` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `job_group` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器主键ID&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `job_cron` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;128&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;任务执行CRON&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `job_desc` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `add_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `update_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `author` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;64&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;作者&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `alarm_email` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;报警邮件&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_route_strategy` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器路由策略&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_handler` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器任务handler&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_param` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;512&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器任务参数&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_block_strategy` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;阻塞处理策略&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_timeout` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;任务执行超时时间，单位秒&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_fail_retry_count` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;失败重试次数&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_type` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE类型&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_source` mediumtext COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE源代码&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_remark` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;128&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE备注&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_updatetime` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE更新时间&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `child_jobid` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;子任务ID，多个逗号分隔&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `trigger_status` tinyint(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;调度状态：0-停止，1-运行&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `trigger_last_time` &lt;span class=&#34;type&#34;&gt;bigint&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;13&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;上次调度时间&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `trigger_next_time` &lt;span class=&#34;type&#34;&gt;bigint&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;13&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;下次调度时间&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_log` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;bigint&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `job_group` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器主键ID&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `job_id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;任务，主键ID&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_address` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器地址，本次执行的地址&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_handler` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器任务handler&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_param` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;512&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器任务参数&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_sharding_param` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器任务分片参数，格式如 1/2&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `executor_fail_retry_count` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;失败重试次数&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `trigger_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;调度-时间&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `trigger_code` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;调度-结果&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `trigger_msg` text COMMENT &lt;span class=&#34;string&#34;&gt;&#39;调度-日志&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `handle_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行-时间&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `handle_code` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行-状态&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `handle_msg` text COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行-日志&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `alarm_status` tinyint(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;告警状态：0-默认、1-无需告警、2-告警成功、3-告警失败&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  KEY `I_trigger_time` (`trigger_time`),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  KEY `I_handle_code` (`handle_code`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_log_report` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `trigger_day` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;调度-时间&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `running_count` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;运行中-日志数量&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `suc_count` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行成功-日志数量&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `fail_count` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行失败-日志数量&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;UNIQUE&lt;/span&gt; KEY `i_trigger_day` (`trigger_day`) &lt;span class=&#34;keyword&#34;&gt;USING&lt;/span&gt; BTREE&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_logglue` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `job_id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;任务，主键ID&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_type` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE类型&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_source` mediumtext COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE源代码&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_remark` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;128&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE备注&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `add_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `update_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_registry` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `registry_group` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `registry_key` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `registry_value` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `update_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  KEY `i_g_k_v` (`registry_group`,`registry_key`,`registry_value`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_group` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `app_name` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;64&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器AppName&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `title` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器名称&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `address_type` tinyint(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器地址类型：0=自动注册、1=手动录入&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `address_list` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;512&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器地址列表，多地址逗号分隔&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_user` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `username` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;账号&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `password` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;密码&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `role` tinyint(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;角色：0-普通用户、1-管理员&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `permission` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;权限：执行器ID列表，多个逗号分割&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;UNIQUE&lt;/span&gt; KEY `i_username` (`username`) &lt;span class=&#34;keyword&#34;&gt;USING&lt;/span&gt; BTREE&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_lock` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `lock_name` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;锁名称&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`lock_name`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;INSERT INTO&lt;/span&gt; `xxl_job_group`(`id`, `app_name`, `title`, `address_type`, `address_list`) &lt;span class=&#34;keyword&#34;&gt;VALUES&lt;/span&gt; (&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;xxl-job-executor-sample&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;示例执行器&#39;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;INSERT INTO&lt;/span&gt; `xxl_job_info`(`id`, `job_group`, `job_cron`, `job_desc`, `add_time`, `update_time`, `author`, `alarm_email`, `executor_route_strategy`, `executor_handler`, `executor_param`, `executor_block_strategy`, `executor_timeout`, `executor_fail_retry_count`, `glue_type`, `glue_source`, `glue_remark`, `glue_updatetime`, `child_jobid`) &lt;span class=&#34;keyword&#34;&gt;VALUES&lt;/span&gt; (&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;0 0 0 * * ? *&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;测试任务1&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;2018-11-03 22:21:31&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;2018-11-03 22:21:31&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;XXL&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;FIRST&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;demoJobHandler&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;SERIAL_EXECUTION&#39;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;BEAN&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;GLUE代码初始化&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;2018-11-03 22:21:31&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;&#39;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;INSERT INTO&lt;/span&gt; `xxl_job_user`(`id`, `username`, `password`, `role`, `permission`) &lt;span class=&#34;keyword&#34;&gt;VALUES&lt;/span&gt; (&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;admin&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;e10adc3949ba59abbe56e057f20f883e&#39;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;INSERT INTO&lt;/span&gt; `xxl_job_lock` ( `lock_name`) &lt;span class=&#34;keyword&#34;&gt;VALUES&lt;/span&gt; ( &lt;span class=&#34;string&#34;&gt;&#39;schedule_lock&#39;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;commit&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;docker-compose.yml&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;version:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#34;3&#34;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;services:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;xxl-job-admin:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;restart:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;always&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;image:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;xuxueli/xxl-job-admin:3.1.1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;container_name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;xxl-job-admin&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;volumes:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;./data/logs:/data/applogs&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;ports:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#34;11001:8800&#34;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;environment:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;PARAMS:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --server.port=8800&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --server.servlet.context-path=/xxl-job-admin&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --spring.datasource.url=jdbc:mysql://192.168.11.122:3306/xxl_job?useUnicode=true&amp;amp;characterEncoding=UTF-8&amp;amp;autoReconnect=true&amp;amp;serverTimezone=Asia/Shanghai&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --spring.datasource.username=root&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --spring.datasource.password=mysql_XH8h7N&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --xxl.job.accessToken=onelovehzs888&#39;&lt;/span&gt;  &lt;span class=&#34;comment&#34;&gt;#代码里面需要指定的token&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;启动&#34;&gt;&lt;a href=&#34;#启动&#34; class=&#34;headerlink&#34; title=&#34;启动&#34;&gt;&lt;/a&gt;启动&lt;/h2&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;docker-compose up -d&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/figure&gt;

